    void screenshot(String name)throws Exception{
        Bitmap image=Bitmap.createBitmap(activity.root.getWidth(),activity.root.getHeight(),Bitmap.Config.ARGB_8888);CountDownLatch copied=new CountDownLatch(1);int[] status={-1};
        if(!await(()->activity.hasWindowFocus()&&activity.scene.getHolder().getSurface().isValid()))throw new IOException("TV left the test activity before capture");
        runOnMainSync(()->{try{PixelCopy.request(activity.scene,image,result->{status[0]=result;copied.countDown();},new Handler(Looper.getMainLooper()));}catch(IllegalArgumentException e){copied.countDown();}});
        if(!copied.await(8,TimeUnit.SECONDS)||status[0]!=PixelCopy.SUCCESS)throw new IOException("Native surface capture failed: "+status[0]);
        // SurfaceView has a separate native buffer. Composite the actual overlay views in layout order.
        // This bypasses a Xiaomi system screenshot scaling bug, without changing any display settings.
        runOnMainSync(()->{android.graphics.Canvas canvas=new android.graphics.Canvas(image);for(int i=0;i<activity.root.getChildCount();i++){View v=activity.root.getChildAt(i);if(v==activity.scene||v.getVisibility()!=View.VISIBLE)continue;canvas.save();canvas.translate(v.getLeft(),v.getTop());v.draw(canvas);canvas.restore();}});
        File folder=getTargetContext().getExternalFilesDir("qa");folder.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(folder,name))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();
    }
